function detectDomainAuthThreat(input) {
  const rawEmail = String(input && input.rawEmail || '');
  const password = String(input && input.password || '');

  if (isClearDomainLoginSqlInjection(rawEmail)) {
    return { detected: true, field: 'email', kind: 'sql_injection' };
  }

  // Password adalah nilai opaque yang diteruskan sebagai JSON ke provider Auth, bukan bagian
  // dari query SQL. Tolak hanya bentuk byte/control yang tidak valid agar password sah tidak
  // dapat memicu ban permanen palsu, sementara scanner SQLi tetap aktif pada email/struktur request.
  const passwordBytes = Buffer.byteLength(password, 'utf8');
  if (!passwordBytes || passwordBytes > 4096 || /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(password)) {
    return { detected: true, field: 'password', kind: 'opaque_password_invalid' };
  }

  return { detected: false, field: '', kind: '' };
}

function isStrictDomainLoginEmail(email) {
  const value = String(email || '').trim();
  if (!/^[a-z0-9@.]+$/.test(value)) return false;
  if ((value.match(/@/g) || []).length !== 1) return false;
  if (value.startsWith('.') || value.endsWith('.') || value.includes('..')) return false;
  return /^[a-z0-9]+(?:\.[a-z0-9]+)*@[a-z0-9]+(?:\.[a-z0-9]+)+$/.test(value);
}

function isStrictDomainAccountEmail(email) {
  const value = String(email || '').trim();
  if (!/^[a-z0-9@.-]+$/.test(value)) return false;
  if ((value.match(/@/g) || []).length !== 1) return false;
  if (value.startsWith('.') || value.endsWith('.') || value.includes('..')) return false;
  return /^[a-z0-9]+(?:\.[a-z0-9]+)*@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$/.test(value);
}

function isAllowedDomainAuthEmail(email) {
  const value = normalizeAuthEmail(email);
  if (!isStrictDomainAccountEmail(value)) return false;
  const domain = value.slice(value.lastIndexOf('@') + 1);
  let activeDomain = '';
  try { activeDomain = diracBaseDomainV250(); } catch (_) { return false; }
  return domain === activeDomain
    || domain === 'gmail.com'
    || domain === 'icloud.com'
    || domain === 'outlook.com'
    || domain === 'yahoo.com';
}

function isClearDomainLoginSqlInjection(value) {
  const samples = buildLoginSecurityInspectionSamples(value);
  const highRiskPatterns = [
    /\bor\s+1\s*=\s*1\b/i,
    /\band\s+1\s*=\s*1\b/i,
    /\bunion\s+(?:all\s+)?select\b/i,
    /\bdrop\s+table\b/i,
    /\bpg_sleep\s*\(/i,
    /\bsleep\s*\(/i,
    /\bbenchmark\s*\(/i,
    /admin\s*['"`]\s*--/i,
    /['"`]\s*(?:or|and)\s+['"`]?\w+['"`]?\s*=\s*['"`]?\w+/i,
    /['"`]\s*--/i,
    /\/\*/i,
    /\*\//i,
    /;\s*(?:select|insert|update|delete|drop|alter|truncate|create)\b/i,
    /\b(?:information_schema|pg_catalog|sqlite_master)\b/i
  ];
  return samples.some((sample) => highRiskPatterns.some((pattern) => pattern.test(sample)));
}

function buildLoginSecurityInspectionSamples(value) {
  const raw = String(value || '');
  const plusAsSpace = raw.replace(/\+/g, ' ');
  const samples = new Set([raw, raw.toLowerCase(), plusAsSpace, plusAsSpace.toLowerCase()]);
  let current = raw;
  for (let i = 0; i < 2; i += 1) {
    try {
      const decoded = decodeURIComponent(current);
      samples.add(decoded);
      samples.add(decoded.toLowerCase());
      samples.add(decoded.replace(/\+/g, ' '));
      samples.add(decoded.replace(/\+/g, ' ').toLowerCase());
      if (decoded === current) break;
      current = decoded;
    } catch (_) {
      break;
    }
  }
  return Array.from(samples).map((sample) => String(sample).slice(0, 2000));
}

