async function domainLogout(req, res) {
  if (req.method !== 'POST') return res.status(405).json({ ok: false, message: 'Gunakan POST.' });

  // Publish success only after revocation; unavailable persistence must remain retryable.
  let revocation;
  try {
    revocation = await revokeCurrentDomainProtectedSessionSafe(req, 'manual_logout');
  } catch (_) {
    revocation = null;
  }
  if (!revocation || (revocation.ok !== true && revocation.reason !== 'no_user')) {
    return res.status(503).json({
      ok: false,
      code: 'LOGOUT_REVOCATION_UNCONFIRMED',
      message: 'Pencabutan sesi belum dikonfirmasi. Silakan coba logout lagi.'
    });
  }

  clearCurrentRequestSessionCookiesV235(req, res);
  appendSetCookie(res, [
    makeCookie(diracCentralDeviceSessionCookieNameV223(), '', { maxAge: 0, domain: '' }),
    makeCookie(diracCentralDeviceCookieNameV221(), '', { maxAge: 0, domain: '' })
  ]);

  return res.status(200).json({
    ok: true,
    message: 'Logout berhasil.'
  });
}

async function domainCheck(req, res) {
  if (req.method !== 'GET') return res.status(405).json({ ok: false, message: 'Gunakan GET.' });

  const user = await requireDomainUser(req, res);
  if (!user) return;

  const domain = normalizeDomain(req.query && req.query.domain);

  if (!domain) {
    return res.status(400).json({ ok: false, message: 'Domain wajib diisi.' });
  }

  const checkApi = requiredEnv('DOMAIN_CHECK_API');
  const response = await fetch(`${checkApi}?domain=${encodeURIComponent(domain)}`);
  const data = await parseFetchResponse(response, 512 * 1024).catch(() => ({}));

  return res.status(response.status).json(data);
}

async function domainCheckout(req, res) {
  if (req.method !== 'POST') return res.status(405).json({ ok: false, message: 'Gunakan POST.' });
  const access = await requireDomainDashboardAccess(req, res);
  if (!access) return;
  return res.status(410).json({ ok: false, code: 'DOMAIN_ORDERS_RETIRED', retired: true, message: 'Layanan pesanan domain telah dinonaktifkan.' });
}


