function customerSecurityDeviceName(userAgent) {
  const ua = String(userAgent || '');
  if (/iPhone/i.test(ua)) return 'iPhone';
  if (/iPad/i.test(ua)) return 'iPad';
  if (/Android/i.test(ua)) return /Mobile/i.test(ua) ? 'Android Phone' : 'Android Tablet';
  if (/Macintosh|Mac OS X/i.test(ua)) return 'Mac';
  if (/Windows/i.test(ua)) return 'Windows PC';
  if (/Linux/i.test(ua)) return 'Linux Device';
  return 'Unknown Device';
}

function customerSecurityBrowserName(userAgent) {
  const ua = String(userAgent || '');
  if (/Edg\//i.test(ua)) return 'Microsoft Edge';
  if (/OPR\//i.test(ua)) return 'Opera';
  if (/CriOS\//i.test(ua)) return 'Chrome iOS';
  if (/Chrome\//i.test(ua)) return 'Chrome';
  if (/FxiOS\//i.test(ua)) return 'Firefox iOS';
  if (/Firefox\//i.test(ua)) return 'Firefox';
  if (/Safari\//i.test(ua)) return 'Safari';
  return 'Unknown Browser';
}

function customerSecurityOperatingSystem(userAgent) {
  const ua = String(userAgent || '');
  if (/iPhone|iPad|iPod/i.test(ua)) return 'iOS';
  if (/Android/i.test(ua)) return 'Android';
  if (/Windows NT/i.test(ua)) return 'Windows';
  if (/Mac OS X|Macintosh/i.test(ua)) return 'macOS';
  if (/Linux/i.test(ua)) return 'Linux';
  return 'Unknown OS';
}

async function customerSecurityWriteSessionTelemetry(customerId, fingerprint) {
  const base = {
    customer_id: customerId,
    device_name: fingerprint.device_name,
    browser_name: fingerprint.browser_name,
    operating_system: fingerprint.operating_system,
    user_agent: fingerprint.user_agent,
    ip_address: fingerprint.ip_address || null,
    country: null,
    city: null,
    metadata: {
      source: 'customer_security_overview',
      auto_detected: true
    }
  };

  await supabaseFetch('/rest/v1/security_customer_login_logs', {
    method: 'POST',
    auth: 'service',
    body: [{
      ...base,
      event_type: 'login_success',
      status: 'success',
      risk_level: 'low'
    }]
  }).catch(() => null);

  await supabaseFetch('/rest/v1/security_customer_events', {
    method: 'POST',
    auth: 'service',
    body: [{
      ...base,
      event_type: 'login_from_new_device',
      status: 'info',
      risk_level: 'low',
      description: 'Perangkat terdeteksi otomatis saat membuka halaman keamanan.'
    }]
  }).catch(() => null);
}

function diracSecurityRedactDiagnosticV210(value, maximum = 180) {
  const limit = Math.max(40, Math.min(400, Number(maximum || 180)));
  let text = '';
  if (value && typeof value === 'object') {
    text = String(value.code || value.name || value.message || 'internal_error');
  } else {
    text = String(value || 'internal_error');
  }
  const token = text.trim();
  // Provider free text can contain complete failing rows, names, or addresses.
  // Keep structural codes only; partial pattern redaction cannot protect them.
  const structuralCode = /^(?:(?:DIRAC|DATA_PROTECTION|CUSTOMER_SECURITY|RECOVERY|SUPABASE|PASSWORD|AUTH|LOGIN|REGISTER|SESSION|DOMAIN|CENTRAL|SECURITY|MIDTRANS|ORDER|CHECKOUT|PAYMENT|PUBLIC_PRODUCTS|ERR)_[A-Z0-9_]+|PGRST(?:116|125|202|204|205)|(?:42P01|42703|42501|23505|23503|23502|57014|53300|40P01)|(?:ECONNRESET|ECONNREFUSED|ETIMEDOUT|ENOTFOUND|EAI_AGAIN)|(?:Type|Range|Syntax|Reference|URI|Eval|Aggregate|Abort)?Error|internal_error|unknown_error)$/.test(token);
  return structuralCode && token.length <= 120 ? token.slice(0, limit) : '[redacted-diagnostic]';
}

function customerSecuritySafeLogError(error) {
  return diracSecurityRedactDiagnosticV210(error, 180);
}



